import{_ as a,a0 as s,w as r,s as u,ao as d,I as n,x as e,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Spotify 原生Linux客户端更新，暗黑风格来袭 | LCTT x X-CMD","titleTemplate":false,"description":"Spotify 原生Linux客户端更新，暗黑风格来袭 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Spotify 原生Linux客户端更新，暗黑风格来袭 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Spotify 原生Linux客户端更新，暗黑风格来袭 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Native Spotify for Linux Client Updated With New Dark Design","title":"Spotify 原生Linux客户端更新，暗黑风格来袭","tag":"201405","desc":""},"relativePath":"201405/Native Spotify for Linux Client Updated With New Dark Design.md","filePath":"[post].md"}'),f={name:"201405/Native Spotify for Linux Client Updated With New Dark Design.md"};function l(y,t,m,x,g,S){const p=s("Link");return r(),u("div",null,[t[11]||(t[11]=d(`<h1 id="spotify-原生linux客户端更新-暗黑风格来袭" tabindex="-1">Spotify 原生Linux客户端更新，暗黑风格来袭 <a class="header-anchor" href="#spotify-原生linux客户端更新-暗黑风格来袭" aria-label="Permalink to “Spotify 原生Linux客户端更新，暗黑风格来袭”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/05/spotify.jpg" alt=""></p><p><strong>继streaming service上个月在其它平台上发布它的应用之后，以同样的扁平化和黑色风格的设计，Linux版本的Spotify客户端也发布了更新。</strong></p><p>金属质感的灰色元素和白色清爽的条区设计形成了基于黑色的风格，以黑色和浅黑色的颜色为主。甚至公司的绿色的商标也不能幸免，以奇怪的颜色出现在各种地方。</p><p>在作曲家和个人资料条目中图片的设计上均采用了圆形的设计元素，并且在导航栏和播放控制按钮的地方采用了iOS 7风格。</p><p>Spotify官方说道这种设计风格突出了软件的内容，他们将之比作“<em>熄掉所有灯光的剧场。</em>”</p><p>除了吸引你眼球的这些改变，还有一些你可能错过的不易察觉的变化。这包括Open SSL 1.0.x的使用、使用<em>libavcodec54</em>来实现本地音乐重放以及播放曲目变化时对本地系统通知的调用支持。</p><p>现在，该软件已不再提供32位的版本。</p><p>由于长期处于预览阶段，Linux下的原生Spotify客户端<strong>支持免费和订阅账户</strong>。</p><h3 id="安装spotify" tabindex="-1">安装Spotify <a class="header-anchor" href="#安装spotify" aria-label="Permalink to “安装Spotify”">​</a></h3><p>要在Ubuntu 14.04 LTS上安装Spotify，你可以打开终端，然后输入下面的命令。</p><p>首先将Spotify官方的软件仓库添加到你的软件源列表中：</p><pre><code>sudo sh -c &#39;echo &quot;deb http://repository.spotify.com stable non-free&quot; &gt; /etc/apt/sources.list.d/spotify.list&#39;
</code></pre><p>添加该软件仓库的安全密钥来避免不必要的错误：</p><pre><code>sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys 94558F59
</code></pre><p>最后，更新并且安装Spotify：</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install spotify-client-qt
</code></pre><p>安装完成后就可以从Dash启动Spotify了。</p><hr>`,19)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),i(p,{href:"http://www.omgubuntu.co.uk/2014/05/spotify-linux-preview-update-new-design"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.omgubuntu.co.uk/2014/05/spotify-linux-preview-update-new-design",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=e("译者：",-1)),i(p,{href:"https://github.com/JonathanKang"},{default:o(()=>[...t[2]||(t[2]=[e("JonathanKang",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),i(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),i(p,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const C=a(f,[["render",l]]);export{w as __pageData,C as default};
